\title{A Universal Hecke Convolution Law for Divisor-Power Sums,\\
with Application to the $E_8$ Theta Series}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
The Siegel--Weil identity in rank $8$ asserts that the theta series of the even
unimodular lattice $E_8$ equals the weight-$4$ Eisenstein series $E_4$. At the
level of Fourier coefficients this is the classical formula
$r(n) = 240\,\sigma_3(n)$, where $r(n)$ counts the lattice vectors of squared
length $2n$ and $\sigma_3(n) = \sum_{d\mid n} d^3$. The arithmetic content of
this identity---that $240\,\sigma_3$ inherits the full Hecke-eigenform structure
of $E_4$---is encapsulated in the global convolution law
$\sigma_3(m)\sigma_3(n) = \sum_{d \mid \gcd(m,n)} d^3\,\sigma_3(mn/d^2)$.
We prove that this law is not special to weight $4$: for \emph{every} exponent
$s$ the divisor-power sum $\sigma_s$ satisfies the identical convolution
identity. We give a complete, elementary derivation resting on a single
geometric double-sum identity, and we extract two families of consequences:
(i) the Hecke operator eigenvalue relation
$\sigma_s(p)\sigma_s(n) = \sigma_s(pn) + \Iv{p\mid n}\,p^s\,\sigma_s(n/p)$,
valid for \emph{all} $n$; and (ii) the growth bound $n^s \le \sigma_s(n)$. Both
are transported back to the $E_8$ representation numbers, yielding
$r(p)r(n) = 240(r(pn) + \Iv{p\mid n}\,p^3\,r(n/p))$ and $240\,n^3 \le r(n)$.
Every result is stated for general $s$; the classical $E_8$ statement is
recovered verbatim as the case $s = 3$.
\end{abstract}

\maketitle

\section{Introduction}

Among all lattices in Euclidean space, the even unimodular lattice
$E_8 \subset \R^8$ is exceptional. It is the unique even unimodular lattice in
its dimension, it realizes the densest lattice sphere packing in $\R^8$, and its
automorphism group is the Weyl group of the exceptional root system $E_8$. A
fundamental invariant of a lattice $\Lambda$ is its \emph{theta series}
\[
\theta_\Lambda(\tau) = \sum_{x \in \Lambda} q^{\langle x, x\rangle / 2},
\qquad q = e^{2\pi i \tau},\ \operatorname{Im}\tau > 0,
\]
whose coefficients record how many lattice vectors have each given squared
length. For an even unimodular lattice of rank $8$, $\theta_\Lambda$ is a modular
form of weight $4$ for $\mathrm{SL}_2(\Z)$. Because the space of such forms is
one-dimensional and spanned by the Eisenstein series $E_4$, and both
$\theta_\Lambda$ and $E_4$ have constant term $1$, they coincide:
\[
\theta_{E_8} = E_4 = 1 + 240 \sum_{n\ge 1} \sigma_3(n)\,q^n.
\]
This is the rank-$8$ case of the \emph{Siegel--Weil identity}. In rank $8$ the
relevant genus has a single class, so the general average over a genus
degenerates to the single lattice $E_8$, and the identity becomes the sharp
coefficient formula
\[
r(n) = 240\,\sigma_3(n),
\qquad r(n) = \#\{x \in E_8 : \langle x,x\rangle = 2n\},\quad
\sigma_3(n) = \sum_{d\mid n} d^3.
\]

The purpose of this paper is to isolate the \emph{arithmetic backbone} of this
identity and to generalize it. The statement $\theta_{E_8} = E_4$ is equivalent
to $240\,\sigma_3$ being a Hecke eigenform, and this eigenform property is
captured, purely arithmetically, by the convolution law
\begin{equation}\tag{$\ast$}
\sigma_3(m)\,\sigma_3(n) = \sum_{d \mid \gcd(m,n)} d^3\,\sigma_3\!\left(\frac{mn}{d^2}\right).
\end{equation}
Our main results are: (1) the convolution law $(\ast)$ holds with $3$ replaced
by any exponent $s$ (Theorem~\ref{thm:universal}); (2) a global Hecke $T_p$
relation valid for every $n$ (Theorem~\ref{thm:tp}); and (3) their consequences
for the $E_8$ representation numbers (Section~\ref{sec:e8}). The development is
elementary and self-contained; the single nontrivial ingredient is a
combinatorial identity for products of finite geometric progressions.

\section{Definitions and notation}

Throughout, $s,m,n,p,r,a,b$ denote nonnegative integers, $p$ a prime where
stated. We write $\Iv{P}$ for the Iverson bracket (equal to $1$ if $P$ holds and
$0$ otherwise) and $v_p(n)$ for the $p$-adic valuation.

\begin{definition}[Divisor-power sum]
For $s \ge 0$ and $n \ge 1$, $\sigma_s(n) = \sum_{d\mid n} d^s$, the sum over
positive divisors of $n$. By convention $\sigma_s(0)=0$.
\end{definition}

\begin{definition}[$E_8$ representation numbers]
With $E_8$ the even unimodular rank-$8$ lattice,
$r(n) = \#\{x\in E_8 : \langle x,x\rangle = 2n\}$. Motivated by the Siegel--Weil
identity we set $r_{E_8}(n) = 240\,\sigma_3(n)$; the classical theorem is
$r(n) = r_{E_8}(n)$.
\end{definition}

\begin{definition}[Hecke convolution]\label{def:hecke}
For $s,m,n\ge 0$,
$\displaystyle H_s(m,n) = \sum_{d\mid \gcd(m,n)} d^s\,\sigma_s(mn/d^2).$
Immediately $H_s(0,n)=H_s(m,0)=0$.
\end{definition}

We use freely that $\sigma_s$ is \emph{multiplicative}: if $\gcd(m,n)=1$ then
$\sigma_s(mn) = \sigma_s(m)\sigma_s(n)$.

\section{The geometric double-sum identity}

\begin{lemma}[Geometric double sum]\label{lem:geom}
For all $q,a,b\ge 0$,
\[
\Bigl(\sum_{i=0}^{a} q^{\,i}\Bigr)\Bigl(\sum_{j=0}^{b} q^{\,j}\Bigr)
   = \sum_{i=0}^{\min(a,b)} q^{\,i}\,\Bigl(\sum_{\ell=0}^{a+b-2i} q^{\,\ell}\Bigr).
\]
\end{lemma}

\begin{proof}
By symmetry assume $a\le b$. The left side is
$\sum_{i=0}^a\sum_{j=0}^b q^{i+j}$, the sum of $q^{i+j}$ over the rectangle
$\{(i,j):0\le i\le a,\ 0\le j\le b\}$. Grouping by the smaller coordinate $i$
(for $0\le i\le a$) produces, for each $i$, a strip whose exponents $i+\ell$
range over $\ell = 0,\dots,a+b-2i$; these strips partition the rectangle. The
identity is verified formally by induction on $a$: the base case $a=0$ is
immediate, and the inductive step peels off the strip $i=a$, contributing
$q^a\sum_{\ell=0}^{b-a}q^\ell$, and rewrites the remainder via the inductive
hypothesis with $(a-1,b-1)$; telescoping of partial geometric sums closes the
computation.
\end{proof}

\section{Prime-power structure}

\begin{lemma}[Geometric form at prime powers]\label{lem:ppow}
For a prime $p$ and $r\ge 0$,
$\displaystyle \sigma_s(p^r)=\sum_{i=0}^{r} p^{\,si}=1+p^s+\cdots+p^{rs}.$
\end{lemma}

\begin{proof}
The divisors of $p^r$ are $p^0,\dots,p^r$; raising to the $s$-th power and
summing gives the claim.
\end{proof}

\begin{corollary}\label{cor:prime}
$\sigma_s(p) = 1 + p^s$ for every prime $p$.
\end{corollary}

\begin{lemma}[Three-term Hecke recurrence at a prime power]\label{lem:rec}
For a prime $p$ and $r\ge 0$,
$\sigma_s(p^{r+2}) + p^s\,\sigma_s(p^r) = \sigma_s(p)\,\sigma_s(p^{r+1}).$
\end{lemma}

\begin{proof}
Substitute Lemma~\ref{lem:ppow} and $\sigma_s(p)=1+p^s$. Both sides expand to
$1 + 2\sum_{i=1}^{r+1}p^{si} + p^{s(r+2)}$.
\end{proof}

\begin{lemma}[Hecke convolution at prime powers]\label{lem:convppow}
For a prime $p$ and $a,b\ge 0$,
$H_s(p^a,p^b) = \sigma_s(p^a)\,\sigma_s(p^b).$
\end{lemma}

\begin{proof}
Since $\gcd(p^a,p^b)=p^{\min(a,b)}$ with divisors $p^0,\dots,p^{\min(a,b)}$,
writing $d=p^i$ gives $d^s=p^{si}$ and $p^ap^b/d^2 = p^{a+b-2i}$, so by
Lemma~\ref{lem:ppow},
\[
H_s(p^a,p^b) = \sum_{i=0}^{\min(a,b)} p^{si}\sum_{\ell=0}^{a+b-2i}p^{s\ell}.
\]
By Lemma~\ref{lem:geom} with $q=p^s$ this equals
$\bigl(\sum_{i=0}^a p^{si}\bigr)\bigl(\sum_{j=0}^b p^{sj}\bigr)
= \sigma_s(p^a)\sigma_s(p^b)$.
\end{proof}

\section{The universal Hecke convolution identity}

\begin{lemma}[Multiplicativity of $H_s$]\label{lem:Hmult}
If $\gcd(m,m')=\gcd(n,n')=\gcd(m,n')=\gcd(m',n)=1$, then
$H_s(mm',nn') = H_s(m,n)\,H_s(m',n').$
\end{lemma}

\begin{proof}
Under these hypotheses $\gcd(mm',nn') = \gcd(m,n)\gcd(m',n')$ with coprime
factors, so each $d\mid\gcd(mm',nn')$ factors uniquely as $d=xy$ with
$x\mid\gcd(m,n)$, $y\mid\gcd(m',n')$. Since
$mm'nn'/(xy)^2 = (mn/x^2)(m'n'/y^2)$ with coprime factors, multiplicativity of
$\sigma_s$ splits each summand and the double sum factors as
$H_s(m,n)H_s(m',n')$.
\end{proof}

\begin{corollary}[Coprime collapse]\label{cor:coprime}
If $\gcd(m,n)=1$ then $H_s(m,n) = \sigma_s(m)\sigma_s(n)$.
\end{corollary}

\begin{theorem}[Universal Hecke convolution identity]\label{thm:universal}
For every exponent $s\ge 0$ and all $m,n\ge 0$,
\[
\sigma_s(m)\,\sigma_s(n)
   = \sum_{d\mid\gcd(m,n)} d^s\,\sigma_s\!\left(\frac{mn}{d^2}\right) = H_s(m,n).
\]
\end{theorem}

\begin{proof}
The case $m=0$ or $n=0$ is immediate. For positive $m,n$ we induct strongly on
$m$. If $\gcd(m,n)=1$, apply Corollary~\ref{cor:coprime}. Otherwise choose a
prime $p\mid\gcd(m,n)$ and write $m=p^am'$, $n=p^bn'$ with $a=v_p(m)\ge1$,
$b=v_p(n)\ge1$, $p\nmid m'$, $p\nmid n'$; then $m'<m$. The four coprimality
conditions of Lemma~\ref{lem:Hmult} hold for $(p^a,m')$, $(p^b,n')$, so
$H_s(m,n) = H_s(p^a,p^b)\,H_s(m',n')$. By Lemma~\ref{lem:convppow},
$H_s(p^a,p^b) = \sigma_s(p^a)\sigma_s(p^b)$, and by induction
$H_s(m',n') = \sigma_s(m')\sigma_s(n')$. Regrouping with multiplicativity of
$\sigma_s$ gives $H_s(m,n) = \sigma_s(p^am')\sigma_s(p^bn') =
\sigma_s(m)\sigma_s(n)$.
\end{proof}

\begin{corollary}[The $E_8$ / weight-$4$ identity]\label{cor:e8}
Taking $s=3$,
$\sigma_3(m)\sigma_3(n) = \sum_{d\mid\gcd(m,n)} d^3\,\sigma_3(mn/d^2)$,
the arithmetic backbone of $\theta_{E_8}=E_4$, i.e.\ of $r(n)=240\,\sigma_3(n)$.
\end{corollary}

\section{The global Hecke operator relation}

\begin{theorem}[Hecke $T_p$ eigenvalue relation]\label{thm:tp}
For every prime $p$, every exponent $s$, and every $n\ge 0$,
\[
\sigma_s(p)\,\sigma_s(n) = \sigma_s(pn) + \Iv{p\mid n}\,p^s\,\sigma_s(n/p).
\]
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:universal} with $m=p$. If $p\nmid n$ then $\gcd(p,n)=1$
and only $d=1$ contributes: $\sigma_s(p)\sigma_s(n)=\sigma_s(pn)$. If $p\mid n$
then $\gcd(p,n)=p$, and the divisors $d=1,p$ contribute $\sigma_s(pn)$ and
$p^s\sigma_s(pn/p^2)=p^s\sigma_s(n/p)$ respectively.
\end{proof}

\begin{proposition}[Growth bound]\label{prop:growth}
For $n\ge 1$, $\ n^s\le\sigma_s(n)$.
\end{proposition}

\begin{proof}
The divisor $n$ contributes the term $n^s$ to the nonnegative sum
$\sigma_s(n)=\sum_{d\mid n}d^s$.
\end{proof}

\section{Consequences for the $E_8$ representation numbers}\label{sec:e8}

\begin{theorem}[Cubic lower bound]\label{thm:e8ge}
For $n\ge 1$, $\ 240\,n^3\le r_{E_8}(n)$.
\end{theorem}

\begin{proof}
Multiply the case $s=3$ of Proposition~\ref{prop:growth} by $240$.
\end{proof}

\begin{theorem}[Hecke recurrence for representation numbers]\label{thm:e8tp}
For every prime $p$ and every $n\ge 0$,
\[
r_{E_8}(p)\,r_{E_8}(n) = 240\,\Bigl(r_{E_8}(pn) + \Iv{p\mid n}\,p^3\,r_{E_8}(n/p)\Bigr).
\]
\end{theorem}

\begin{proof}
$r_{E_8}(k)=240\,\sigma_3(k)$, so the left side is
$240^2\sigma_3(p)\sigma_3(n)$. Apply Theorem~\ref{thm:tp} with $s=3$, multiply
by $240^2$, and factor one $240$ from the parenthesis.
\end{proof}

Since $r(n)=r_{E_8}(n)$ by the Siegel--Weil identity, Theorems~\ref{thm:e8ge}
and~\ref{thm:e8tp} describe the true geometric point-counts of $E_8$.

\section{Discussion and future directions}

Isolating the convolution law as a purely arithmetic statement makes the
$E_8=E_4$ identity's arithmetic content independent of modular-forms machinery,
exposes it as one rung of an infinite ladder indexed by $s$, and yields (via
Theorem~\ref{thm:tp}) a fast recursion for $\sigma_s$ and hence $r(n)$.

Natural extensions include: (1) the $\sigma_7$ convolution
$\sigma_7(n) = \sigma_3(n) + 120\sum_{m=1}^{n-1}\sigma_3(m)\sigma_3(n-m)$ arising
from the rank-$16$ Siegel--Weil setting ($E_8\oplus E_8$ and $D_{16}^+$);
(2) the prime-factorization closed form $\sigma_s(n)=\prod_{p\mid n}
(p^{s(v_p(n)+1)}-1)/(p^s-1)$; (3) the Dirichlet-series Euler product
$\sum_n\sigma_s(n)n^{-w} = \zeta(w)\zeta(w-s)$; (4) formalizing the
class-number-one/mass-formula statement underlying the exactness of
$\theta_{E_8}=E_4$; and (5) the rank-$8k$ case for $k\ge 2$, where the theta
series equals $E_{4k}$ only modulo cusp forms.

\section{Conclusion}

The arithmetic heart of the Siegel--Weil identity in rank $8$---the convolution
law obeyed by $\sigma_3$---is a special case of a universal law valid for
$\sigma_s$ of every weight. The proof reduces to a geometric double-sum identity
propagated by multiplicativity. From it we obtained an explicit global Hecke
$T_p$ relation and an elementary growth bound, both transported to the $E_8$
representation numbers. Thus $E_8$'s celebrated formula $r(n)=240\,\sigma_3(n)$
is one distinguished instance of a structure spanning every Eisenstein weight.

