"""Verify the E8 counting formula r(n) = 240 * sigma_3(n) against a direct
enumeration of lattice vectors in the D8+ coordinate model of E8."""
from __future__ import annotations
from math import isqrt
from typing import List

def divisors(n: int) -> List[int]:
    ds = []
    for d in range(1, isqrt(n) + 1):
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
    return sorted(ds)

def sigma3(n: int) -> int:
    return sum(d ** 3 for d in divisors(n)) if n else 0

def e8_count(sq_len: int) -> int:
    """Count E8 vectors of squared length sq_len (all-integer or all-half-integer,
    even coordinate sum)."""
    total = 0
    R = isqrt(sq_len)
    def rec_int(i: int, rem: int, csum: int) -> int:
        if i == 8:
            return 1 if rem == 0 and csum % 2 == 0 else 0
        t = 0
        for x in range(-R, R + 1):
            if x * x <= rem:
                t += rec_int(i + 1, rem - x * x, csum + x)
        return t
    total += rec_int(0, sq_len, 0)
    tgt = 4 * sq_len
    Ry = isqrt(tgt)
    odds = [y for y in range(-Ry, Ry + 1) if y % 2]
    def rec_half(i: int, rem: int, ysum: int) -> int:
        if i == 8:
            return 1 if rem == 0 and ysum % 4 == 0 else 0
        t = 0
        for y in odds:
            if y * y <= rem:
                t += rec_half(i + 1, rem - y * y, ysum + y)
        return t
    total += rec_half(0, tgt, 0)
    return total

for n in range(1, 5):
    print(n, e8_count(2 * n), 240 * sigma3(n), e8_count(2 * n) == 240 * sigma3(n))

"""Numerically confirm the universal Hecke convolution identity
sigma_s(m) sigma_s(n) = sum_{d | gcd(m,n)} d^s sigma_s(mn/d^2)
for a range of exponents s and argument pairs (m, n)."""
from __future__ import annotations
from math import gcd, isqrt
from typing import List

def divisors(n: int) -> List[int]:
    ds = []
    for d in range(1, isqrt(n) + 1):
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
    return sorted(ds)

def sigma(s: int, n: int) -> int:
    return sum(d ** s for d in divisors(n)) if n else 0

def hecke(s: int, m: int, n: int) -> int:
    g = gcd(m, n)
    return sum(d ** s * sigma(s, m * n // (d * d)) for d in divisors(g))

for s in range(0, 6):
    for (m, n) in [(4, 6), (12, 18), (36, 24), (30, 42)]:
        lhs, rhs = sigma(s, m) * sigma(s, n), hecke(s, m, n)
        assert lhs == rhs, (s, m, n)
        print(f"s={s} m={m} n={n}: {lhs} == {rhs}")
print("all convolution checks passed")

"""Demonstrate the global Hecke operator relation
sigma_s(p) sigma_s(n) = sigma_s(pn) + [p|n] p^s sigma_s(n/p)
and use it as a fast recursion to rebuild sigma_s(n) from prime data."""
from __future__ import annotations
from math import isqrt
from typing import List

def divisors(n: int) -> List[int]:
    ds = []
    for d in range(1, isqrt(n) + 1):
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
    return sorted(ds)

def sigma(s: int, n: int) -> int:
    return sum(d ** s for d in divisors(n)) if n else 0

def tp_rhs(s: int, p: int, n: int) -> int:
    corr = p ** s * sigma(s, n // p) if n % p == 0 else 0
    return sigma(s, p * n) + corr

s = 3
