    assert lhs == tp_rhs(s, p, n)
    print(f"p={p} n={n}: sigma3(p)*sigma3(n) = {lhs} = sigma3(pn)+corr")
print("Tp relation verified; eigenvalue sigma3(p) = 1 + p^3 for each prime p")

